import { Badge } from '@liulidesign/core/Badge';

export function Tones() {
  return (
    <view className="flex-row flex-wrap gap-2">
      <Badge label="Draft" data-testid="neutral" />
      <Badge label="New" tone="accent" data-testid="accent" />
      <Badge label="Paid" tone="success" />
      <Badge label="Due soon" tone="warning" />
      <Badge label="Overdue" tone="danger" data-testid="danger" />
    </view>
  );
}

import { Badge } from '@liulidesign/core/Badge';

/** Solid fills stand out; keep one per view. */
export function Solid() {
  return (
    <view className="flex-row flex-wrap gap-2">
      <Badge label="Beta" tone="accent" emphasis="solid" data-testid="solid" />
      <Badge label="Live" tone="success" emphasis="solid" />
      <Badge label="Paused" tone="warning" emphasis="solid" />
      <Badge label="Failed" tone="danger" emphasis="solid" />
    </view>
  );
}

import { Badge } from '@liulidesign/core/Badge';

const dot = [{ d: 'M12 8a4 4 0 1 0 0 8a4 4 0 1 0 0-8z', fill: 'currentColor' }] as const;

export function Sizes() {
  return (
    <view className="flex-row flex-wrap items-center gap-2">
      <Badge label="Small" size="sm" data-testid="small" />
      <Badge label="Online" tone="success" startIcon={<vector paths={dot} viewBox={[0, 0, 24, 24]} className="size-full" />} />
    </view>
  );
}

import { Item } from '@liulidesign/core/Item';
import { Badge } from '@liulidesign/core/Badge';

/** In a pressable row the end content is not read, so the status is repeated in the description. */
export function InARow() {
  return (
    <view className="rounded-container border border-line bg-surface">
      <Item
        label="Invoice 2041"
        description="Overdue, due 3 May"
        endContent={<Badge label="Overdue" tone="danger" size="sm" />}
        hasChevron
        onClick={() => {}}
        data-testid="invoice"
      />
    </view>
  );
}

import { Button } from '@liulidesign/core/Button';

export function Variants() {
  return (
    <view className="flex-row flex-wrap gap-2">
      <Button label="Save changes" variant="primary" data-testid="primary" />
      <Button label="Preview" />
      <Button label="Skip" variant="ghost" />
      <Button label="Delete draft" variant="destructive" />
    </view>
  );
}

import { Button } from '@liulidesign/core/Button';

export function Sizes() {
  return (
    <view className="flex-row flex-wrap items-center gap-2">
      <Button label="Small" size="sm" />
      <Button label="Medium" />
      <Button label="Large" size="lg" />
    </view>
  );
}

import { useView, type View } from '@lingxia/view';
import { Button } from '@liulidesign/core/Button';

type Actions = { publish(): Promise<void> };

/** `clickAction` takes a Logic action as it is; the button shows loading until it settles. */
export function AsyncAction() {
  const { actions } = useView() as View<Actions>;
  return <Button label="Publish" variant="primary" width="content" clickAction={() => actions.publish()} data-testid="publish" />;
}

import { useLocal } from '@lingxia/view';
import { Button } from '@liulidesign/core/Button';

/** The reason is read after the label while disabled. Pass translated copy; Liuli ships none. */
export function DisabledWithReason() {
  const agreed = useLocal('agreed', false);
  return (
    <view className="gap-2">
      <Button
        label="Continue"
        variant="primary"
        width="fill"
        isDisabled={!agreed.value}
        disabledMessage="Accept the terms first"
        data-testid="continue"
      />
      <Button
        label={agreed.value ? 'Withdraw consent' : 'Accept the terms'}
        variant="ghost"
        width="content"
        onClick={() => agreed.set(!agreed.value)}
        data-testid="toggle-terms"
      />
    </view>
  );
}

import { Card } from '@liulidesign/core/Card';

export function Variants() {
  return (
    <view className="gap-3">
      <Card data-testid="outlined">
        <text className="text-callout font-semibold text-text">Outlined</text>
        <text className="text-footnote text-muted">Sits on the page.</text>
      </Card>
      <Card variant="raised">
        <text className="text-callout font-semibold text-text">Raised</text>
        <text className="text-footnote text-muted">Floats above the page.</text>
      </Card>
      <Card variant="sunken">
        <text className="text-callout font-semibold text-text">Sunken</text>
        <text className="text-footnote text-muted">Groups content inside another surface.</text>
      </Card>
    </view>
  );
}

import { Button } from '@liulidesign/core/Button';
import { Card, ClickableCard } from '@liulidesign/core/Card';

/** Actions go in a plain Card, never in a ClickableCard. */
export function WithActions() {
  return (
    <Card>
      <text role="heading" headingLevel={3} className="text-callout font-semibold text-text">Back up your notes</text>
      <text className="text-footnote text-muted">Keep a copy on another device in case this one is lost.</text>
      <view className="flex-row justify-end gap-2">
        <Button label="Not now" variant="ghost" size="sm" />
        <Button label="Turn on" variant="primary" size="sm" data-testid="turn-on" />
      </view>
    </Card>
  );
}

import { useLocal } from '@lingxia/view';
import { ClickableCard } from '@liulidesign/core/Card';

const plans = [
  { id: 'monthly', name: 'Monthly', price: '€4 a month' },
  { id: 'yearly', name: 'Yearly', price: '€40 a year' },
] as const;

/** Choosing one of several: the chosen card is reported as selected. */
export function Choice() {
  const plan = useLocal('plan', 'monthly');
  return (
    <view className="flex-row gap-3">
      {plans.map(item => (
        <ClickableCard
          key={item.id}
          label={`${item.name}, ${item.price}`}
          isSelected={plan.value === item.id}
          onClick={() => plan.set(item.id)}
          className="grow basis-0"
          data-testid={`plan-${item.id}`}
        >
          <text className="text-callout font-semibold text-text">{item.name}</text>
          <text className="text-footnote text-muted">{item.price}</text>
        </ClickableCard>
      ))}
    </view>
  );
}

import { useLocal } from '@lingxia/view';
import { CheckboxInput } from '@liulidesign/core/CheckboxInput';

export function Basic() {
  const digest = useLocal('digest', true);
  return <CheckboxInput bind={digest} label="Weekly digest" description="A summary of your notes every Monday." data-testid="digest" />;
}

import { useLocal } from '@lingxia/view';
import { CheckboxInput } from '@liulidesign/core/CheckboxInput';

/** Owned by the app: the checkbox reports, the app decides. */
export function Controlled() {
  const accepted = useLocal('accepted', false);
  return (
    <CheckboxInput
      value={accepted.value}
      onChange={next => accepted.set(next)}
      label="I accept the terms of service"
      isRequired
      status={accepted.value ? undefined : { type: 'error', message: 'Accept the terms to create the account.' }}
      data-testid="terms"
    />
  );
}

import { useLocal } from '@lingxia/view';
import { CheckboxInput } from '@liulidesign/core/CheckboxInput';

export function Sizes() {
  const small = useLocal('small', false);
  const medium = useLocal('medium', true);
  const large = useLocal('large', false);
  return (
    <view className="gap-2">
      <CheckboxInput bind={small} label="Small" size="sm" />
      <CheckboxInput bind={medium} label="Medium" />
      <CheckboxInput bind={large} label="Large" size="lg" />
    </view>
  );
}

import { Details } from '@liulidesign/core/Details';

const surface = 'gap-1 rounded-container border border-text/10 bg-surface px-5 pt-4 pb-1';

/** One disclosure under the text it qualifies: the summary opens and closes the content under it. */
export function Single() {
  return (
    <view className={surface}>
      <text className="text-body text-text">Team is €8 a month for each active member.</text>
      <Details label="What counts as an active member?" data-testid="active">
        <text className="text-body text-muted">Anyone who opened a shared notebook in the last 30 days. Guests with view access are free.</text>
      </Details>
    </view>
  );
}

import { Details, DetailsGroup } from '@liulidesign/core/Details';

/** An accordion: opening one row closes the one that was open. */
export function Accordion() {
  return (
    <DetailsGroup isExclusive defaultValue="refunds" data-testid="faq">
      <Details value="refunds" label="Can I get a refund?" data-testid="refunds">
        <text className="text-body text-muted">Within 14 days of a payment, in full, from Billing.</text>
      </Details>
      <Details value="export" label="How do I export my notes?" data-testid="export">
        <text className="text-body text-muted">Settings, then Export: Markdown files in one archive, with attachments.</text>
      </Details>
      <Details value="delete" label="What happens when I delete my account?" data-testid="delete">
        <text className="text-body text-muted">Your notes are removed from every device after 30 days. Shared notebooks pass to their next member.</text>
      </Details>
    </DetailsGroup>
  );
}

import { Details, DetailsGroup } from '@liulidesign/core/Details';

/** Several rows open at once. */
export function Independent() {
  return (
    <DetailsGroup>
      <Details label="Shipping" isDefaultOpen>
        <text className="text-body text-muted">Free over €40. Two to four working days.</text>
      </Details>
      <Details label="Returns" isDefaultOpen>
        <text className="text-body text-muted">30 days, in the original packaging.</text>
      </Details>
    </DetailsGroup>
  );
}

import { useLocal } from '@lingxia/view';
import { Button } from '@liulidesign/core/Button';
import { Dialog } from '@liulidesign/core/Dialog';

/** A confirmation that interrupts: Escape and back cancel, a backdrop tap does not; the destructive action is last. */
export function Confirm() {
  const open = useLocal('open', false);
  const deleted = useLocal('deleted', false);
  return (
    <view className="gap-2">
      <Button label="Delete note" variant="destructive" width="content" onClick={() => open.set(true)} data-testid="confirm-open" />
      <text role="status" data-testid="outcome" className="text-footnote text-muted">{deleted.value ? 'Deleted' : 'Not deleted'}</text>
      <Dialog
        isOpen={open.value}
        onOpenChange={next => open.set(next)}
        label="Delete this note?"
        description="It leaves every device you are signed in on."
        size="sm"
        isAlert
        dismissOn="closeRequest"
        data-testid="confirm-dialog"
        actions={
          <>
            <Button label="Cancel" onClick={() => open.set(false)} data-testid="cancel" />
            <Button label="Delete" variant="destructive" onClick={() => { deleted.set(true); open.set(false); }} data-testid="confirm" />
          </>
        }
      />
    </view>
  );
}

import { useLocal } from '@lingxia/view';
import { Button } from '@liulidesign/core/Button';
import { TextInput } from '@liulidesign/core/TextInput';
import { Dialog } from '@liulidesign/core/Dialog';

/**
 * A short form. The draft lives outside the dialog, since closing discards the dialog's own state.
 * Only Escape and back cancel, so a stray backdrop tap does not lose the typing.
 */
export function Form() {
  const open = useLocal('open', false);
  const name = useLocal('name', '');
  return (
    <view className="gap-2">
      <Button label="Rename" width="content" onClick={() => open.set(true)} data-testid="rename-open" />
      <Dialog
        isOpen={open.value}
        onOpenChange={next => open.set(next)}
        label="Rename notebook"
        closeLabel="Close"
        dismissOn="closeRequest"
        data-testid="rename-dialog"
        actions={<Button label="Save" variant="primary" isDisabled={name.value.trim() === ''} onClick={() => open.set(false)} data-testid="save" />}
      >
        <TextInput bind={name} label="Name" hasAutoFocus enterKeyHint="done" onSubmit={() => open.set(false)} data-testid="name" />
      </Dialog>
    </view>
  );
}

import { useLocal } from '@lingxia/view';
import { DropdownMenu, DropdownMenuItem } from '@liulidesign/core/DropdownMenu';

/** A labelled trigger; the menu lines up with its start edge. */
export function Basic() {
  const order = useLocal('order', 'Name');
  return (
    <view className="flex-row items-center gap-3">
      <DropdownMenu label="Sort by" data-testid="sort">
        <DropdownMenuItem label="Name" onClick={() => order.set('Name')} data-testid="sort-name" />
        <DropdownMenuItem label="Last updated" description="Newest first" onClick={() => order.set('Last updated')} data-testid="sort-updated" />
        <DropdownMenuItem label="Size" onClick={() => order.set('Size')} />
      </DropdownMenu>
      <text data-testid="order" className="text-footnote text-muted">{order.value}</text>
    </view>
  );
}

import { useLocal, type VectorPath } from '@lingxia/view';
import { DropdownMenu, DropdownMenuDivider, DropdownMenuItem } from '@liulidesign/core/DropdownMenu';

const dots: VectorPath[] = [{ d: 'M5 12h.01M12 12h.01M19 12h.01', fill: 'none', stroke: 'currentColor', strokeWidth: 3, strokeLinecap: 'round' }];
const trash: VectorPath[] = [{ d: 'M4 7h16M9 7V4h6v3M6 7l1 13h10l1-13', fill: 'none', stroke: 'currentColor', strokeWidth: 2, strokeLinejoin: 'round' }];

/** An icon-only "more" menu at the end of a row, aligned to the row's end edge. */
export function More() {
  const removed = useLocal('removed', false);
  return (
    <view className="flex-row items-center gap-3">
      <text className="grow basis-0 text-body font-medium text-text">{removed.value ? 'Removed' : 'Groceries'}</text>
      <DropdownMenu
        label="More actions"
        isLabelHidden
        icon={<vector aria-hidden paths={dots} viewBox={[0, 0, 24, 24]} className="size-5" />}
        variant="ghost"
        alignment="end"
        data-testid="more"
      >
        <DropdownMenuItem label="Rename" onClick={() => {}} />
        <DropdownMenuItem label="Share" onClick={() => {}} isDisabled />
        <DropdownMenuDivider />
        <DropdownMenuItem
          label="Delete"
          variant="destructive"
          icon={<vector aria-hidden paths={trash} viewBox={[0, 0, 24, 24]} className="size-4" />}
          onClick={() => removed.set(true)}
          data-testid="delete"
        />
      </DropdownMenu>
    </view>
  );
}

import { type VectorPath } from '@lingxia/view';
import { DropdownMenu, DropdownMenuItem } from '@liulidesign/core/DropdownMenu';

const dots: VectorPath[] = [{ d: 'M5 12h.01M12 12h.01M19 12h.01', fill: 'none', stroke: 'currentColor', strokeWidth: 3, strokeLinecap: 'round' }];

/** Rows that each carry a menu: every menu gets its own id, so no row needs one. */
export function InList() {
  const rows = ['Inbox', 'Archive'];
  return (
    <view className="gap-2">
      {rows.map(row => (
        <view key={row} className="flex-row items-center gap-3">
          <text className="grow basis-0 text-body text-text">{row}</text>
          <DropdownMenu
            label={`${row} actions`}
            isLabelHidden
            icon={<vector aria-hidden paths={dots} viewBox={[0, 0, 24, 24]} className="size-5" />}
            variant="ghost"
            size="sm"
            alignment="end"
            data-testid={`menu-${row}`}
          >
            <DropdownMenuItem label="Open" onClick={() => {}} />
          </DropdownMenu>
        </view>
      ))}
    </view>
  );
}

import { useLocal } from '@lingxia/view';
import { DropdownMenu, DropdownMenuItem } from '@liulidesign/core/DropdownMenu';

/** A menu that sets a value: the trigger shows the choice, and the label stays its name. */
export function Value() {
  const appearance = useLocal('appearance', 'System');
  return (
    <view className="flex-row items-center gap-3">
      <text className="grow basis-0 text-body text-text">Appearance</text>
      <DropdownMenu label="Appearance" value={appearance.value} variant="ghost" size="sm" alignment="end" data-testid="appearance">
        {['System', 'Light', 'Dark'].map(option => (
          <DropdownMenuItem key={option} label={option} onClick={() => appearance.set(option)} data-testid={`appearance-${option}`} />
        ))}
      </DropdownMenu>
    </view>
  );
}

import { useLocal } from '@lingxia/view';
import { Field } from '@liulidesign/core/Field';

const periods = [
  { value: 'monthly', label: 'Monthly' },
  { value: 'yearly', label: 'Yearly' },
] as const;

/** A raw select takes Field's label, help and status until Liuli has its own. */
export function WrappedSelect() {
  const period = useLocal('period', '');
  return (
    <Field
      label="Billing period"
      description="You can change it later."
      status={period.value ? undefined : { type: 'warning', message: 'Choose a period to see the price.' }}
      isRequired
      data-testid="field"
    >
      {control => (
        <select
          bind={period}
          aria-label={control['aria-label']}
          aria-describedby={control['aria-describedby']}
          aria-invalid={control['aria-invalid']}
          aria-required={control['aria-required']}
          disabled={control.disabled}
          placeholder="Choose…"
          options={periods}
          data-testid="period"
          className="min-h-control-md px-3 rounded-control border border-line-strong bg-surface text-body text-text"
        />
      )}
    </Field>
  );
}

import { Item } from '@liulidesign/core/Item';

const notes = [
  { id: 'n1', title: 'Groceries', updated: 'Edited today' },
  { id: 'n2', title: 'Trip to the coast', updated: 'Edited yesterday' },
  { id: 'n3', title: 'Reading list', updated: 'Edited last week' },
] as const;

/** Rows that open a page: each is one button named by its title, with the second line as its description. */
export function Navigation() {
  return (
    <view className="rounded-container border border-line bg-surface divide-y divide-line">
      {notes.map(note => (
        <Item key={note.id} label={note.title} description={note.updated} hasChevron onClick={() => {}} data-testid={`note-${note.id}`} />
      ))}
    </view>
  );
}

import { Item } from '@liulidesign/core/Item';

const folder = [{ d: 'M3 7a2 2 0 0 1 2-2h4l2 2h8a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z', fill: 'none', stroke: 'currentColor', strokeWidth: 2, strokeLinejoin: 'round' }] as const;

/** A value at the end of a read-only row, and an icon at the start. */
export function Values() {
  return (
    <view className="rounded-container border border-line bg-surface divide-y divide-line">
      <Item
        label="Version"
        endContent={<text className="text-footnote text-muted">2.4.1</text>}
        data-testid="version"
      />
      <Item
        label="Storage"
        description="Photos and documents"
        startContent={<vector aria-hidden paths={folder} viewBox={[0, 0, 24, 24]} className="size-5" />}
        endContent={<text className="text-footnote text-muted">7.2 GB</text>}
      />
    </view>
  );
}

import { useLocal } from '@lingxia/view';
import { Button } from '@liulidesign/core/Button';
import { Item } from '@liulidesign/core/Item';

/** A row without `onClick` can hold its own control at the end. */
export function WithControl() {
  const signedIn = useLocal('signedIn', true);
  return (
    <view className="rounded-container border border-line bg-surface">
      <Item
        label="Account"
        description={signedIn.value ? 'Signed in' : 'Signed out'}
        endContent={
          <Button
            label={signedIn.value ? 'Sign out' : 'Sign in'}
            size="sm"
            onClick={() => signedIn.set(!signedIn.value)}
            data-testid="account-action"
          />
        }
        data-testid="account"
      />
    </view>
  );
}

import { Item } from '@liulidesign/core/Item';

export function Disabled() {
  return (
    <view className="rounded-container border border-line bg-surface">
      <Item
        label="Export history"
        description="Download every change as a file"
        disabledMessage="Available once a change is saved"
        isDisabled
        hasChevron
        onClick={() => {}}
        data-testid="export"
      />
    </view>
  );
}

import { Item } from '@liulidesign/core/Item';

const notes = [
  { id: 'n1', title: 'Groceries', updated: 'Edited today' },
  { id: 'n2', title: 'Trip to the coast', updated: 'Edited yesterday' },
  { id: 'n3', title: 'Reading list', updated: 'Edited last week' },
] as const;

/** A row that deletes or ends something; the danger tone marks it before it is pressed. */
export function Destructive() {
  return (
    <view className="rounded-container border border-line bg-surface">
      <Item label="Delete account" description="Removes your notes from every device" tone="danger" hasChevron onClick={() => {}} data-testid="delete-row" />
    </view>
  );
}

import { useLocal } from '@lingxia/view';
import { Button } from '@liulidesign/core/Button';
import { ProgressBar } from '@liulidesign/core/ProgressBar';

/** The app words the amount; Liuli formats no numbers. */
export function Determinate() {
  const sent = useLocal('sent', 3);
  return (
    <view className="gap-3">
      <ProgressBar label="Uploading photos" value={sent.value} max={8} valueLabel={`${sent.value} of 8`} data-testid="upload" />
      <Button
        label="Send one more"
        size="sm"
        width="content"
        isDisabled={sent.value === 8}
        onClick={() => sent.set(sent.value + 1)}
        data-testid="more"
      />
    </view>
  );
}

import { ProgressBar } from '@liulidesign/core/ProgressBar';

export function Indeterminate() {
  return <ProgressBar label="Preparing the export" data-testid="export" />;
}

import { ProgressBar } from '@liulidesign/core/ProgressBar';

/** A thin bar under a heading that already says what is happening. */
export function Compact() {
  return (
    <view className="gap-2">
      <text className="text-footnote font-medium text-text">Storage</text>
      <ProgressBar label="Storage used" isLabelHidden size="sm" value={72} valueLabel="7.2 of 10 GB" data-testid="storage" />
    </view>
  );
}

import { Spinner } from '@liulidesign/core/ProgressBar';

export function Spinners() {
  return (
    <view className="flex-row items-center gap-4">
      <Spinner label="Loading" size="sm" />
      <Spinner label="Loading messages" data-testid="spinner" />
      <Spinner label="Loading" size="lg" />
    </view>
  );
}

import { useLocal } from '@lingxia/view';
import { RadioGroup } from '@liulidesign/core/RadioGroup';

const deliveries = [
  { value: 'standard', label: 'Standard', description: '3 to 5 working days, free' },
  { value: 'express', label: 'Express', description: 'Next working day, €6' },
  { value: 'pickup', label: 'Pick up in store', description: 'Ready in two hours' },
];

/** Options with a second line each. */
export function Delivery() {
  const delivery = useLocal<string | null>('delivery', 'standard');
  return <RadioGroup bind={delivery} label="Delivery" options={deliveries} data-testid="delivery" />;
}

import { useLocal } from '@lingxia/view';
import { RadioGroup } from '@liulidesign/core/RadioGroup';

const plans = [
  { value: 'free', label: 'Free', description: 'Up to 3 notebooks, on one device' },
  { value: 'plus', label: 'Plus · €4 a month', description: 'Unlimited notebooks, sync across devices' },
  { value: 'team', label: 'Team · €8 a person', description: 'Shared notebooks, admin controls' },
];

/** Each option a card: the whole card chooses it. */
export function Plans() {
  const plan = useLocal<string | null>('plan', 'plus');
  return <RadioGroup bind={plan} label="Plan" options={plans} variant="card" data-testid="plan" />;
}

import { useLocal } from '@lingxia/view';
import { RadioGroup } from '@liulidesign/core/RadioGroup';

/** Short options, no second line. */
export function Plain() {
  const theme = useLocal<string | null>('theme', 'system');
  return (
    <RadioGroup
      bind={theme}
      label="Appearance"
      description="System follows the device."
      options={[{ value: 'system', label: 'System' }, { value: 'light', label: 'Light' }, { value: 'dark', label: 'Dark' }]}
      data-testid="appearance"
    />
  );
}

import { useLocal } from '@lingxia/view';
import { RadioGroup } from '@liulidesign/core/RadioGroup';

/** Nothing chosen yet, required, after a failed send. */
export function Required() {
  const reason = useLocal<string | null>('reason', null);
  return (
    <RadioGroup
      bind={reason}
      label="Why are you leaving?"
      isRequired
      status={reason.value === null ? { type: 'error', message: 'Choose a reason.' } : undefined}
